package stm32

import (
	"bytes"
	"context"
	"encoding/hex"
	"encoding/json"
	"os"
	"testing"
	"time"

	"github.com/GNSS-BANK/gnss-device-sdk/opu"
)

// These full request frames are generated by the supplied OPU Studio 3.3.0
// encoder, rather than by the SDK under test. No serial device is opened.
func TestRequestsMatchOPUStudio(t *testing.T) {
	data, err := os.ReadFile("testdata/opu_studio_3_3.json")
	if err != nil {
		t.Fatal(err)
	}
	var fixture struct {
		Vectors []struct {
			Name            string `json:"name"`
			Sequence        uint16 `json:"sequence"`
			FrameHex        string `json:"frame_hex"`
			ResponseDataHex string `json:"response_data_hex"`
		} `json:"vectors"`
	}
	if err := json.Unmarshal(data, &fixture); err != nil {
		t.Fatal(err)
	}
	ctx := context.Background()
	config := opu.AxisConfig{Axis: opu.Azimuth, MotorFullStepsPerRev: 200, Microsteps: 8,
		GearNumerator: 18, GearDenominator: 1, MaxStepRateHz: 2000, AccelerationStepsS2: 1000,
		StartStepRateHz: 100, InvertMotor: true, InvertEncoder: true}
	operations := map[string]func(*Client) error{
		"ping":         func(c *Client) error { _, err := c.Ping(ctx, []byte{'O', 'P', 'U', 0}); return err },
		"info":         func(c *Client) error { _, err := c.Info(ctx); return err },
		"diagnostics":  func(c *Client) error { _, err := c.Diagnostics(ctx); return err },
		"set_config":   func(c *Client) error { return c.SetAxisConfig(ctx, config) },
		"get_config":   func(c *Client) error { _, err := c.AxisConfig(ctx, opu.Azimuth); return err },
		"enable":       func(c *Client) error { return c.EnableAxis(ctx, opu.Azimuth) },
		"disable":      func(c *Client) error { return c.DisableAxis(ctx, opu.Polarization) },
		"steps":        func(c *Client) error { return c.MoveSteps(ctx, opu.Polarization, -4294967295) },
		"relative":     func(c *Client) error { return c.MoveRelativeAngle(ctx, opu.Elevation, -12500) },
		"absolute":     func(c *Client) error { return c.MoveAbsoluteAngle(ctx, opu.Azimuth, 270000) },
		"unwrapped":    func(c *Client) error { return c.MoveAbsoluteUnwrapped(ctx, opu.Azimuth, 360000) },
		"stop_all":     func(c *Client) error { return c.Stop(ctx, opu.AllAxes) },
		"stop_axis":    func(c *Client) error { return c.Stop(ctx, opu.Elevation) },
		"estop":        func(c *Client) error { return c.EmergencyStop(ctx) },
		"clear_estop":  func(c *Client) error { return c.ClearEmergencyStop(ctx) },
		"status":       func(c *Client) error { _, err := c.Status(ctx, opu.Elevation); return err },
		"zero_encoder": func(c *Client) error { return c.ZeroEncoder(ctx, opu.Polarization) },
		"zero_command": func(c *Client) error { return c.ZeroCommandPosition(ctx, opu.Elevation) },
		"reference":    func(c *Client) error { return c.ReferenceElevation(ctx, -25000) },
		"target":       func(c *Client) error { _, err := c.Target(ctx, opu.Elevation); return err },
		"link_timeout": func(c *Client) error { return c.SetLinkTimeout(ctx, 3*time.Second) },
	}
	if len(fixture.Vectors) != len(operations) {
		t.Fatal("fixture does not cover all Studio requests")
	}
	for _, v := range fixture.Vectors {
		t.Run(v.Name, func(t *testing.T) {
			want, err := hex.DecodeString(v.FrameHex)
			if err != nil {
				t.Fatal(err)
			}
			reply, err := hex.DecodeString(v.ResponseDataHex)
			if err != nil {
				t.Fatal(err)
			}
			operation, ok := operations[v.Name]
			if !ok {
				t.Fatal("unknown operation")
			}
			p := &fakePort{answer: func(req []byte) []byte { return respond(req, 0, reply) }}
			c, err := New(p, time.Second)
			if err != nil {
				t.Fatal(err)
			}
			defer c.Close()
			c.seq = v.Sequence - 1 // Includes 0xffff -> 0 sequence wrap.
			if err := operation(c); err != nil {
				t.Fatal(err)
			}
			if len(p.writes) != 1 || !bytes.Equal(p.writes[0], want) {
				t.Fatalf("SDK request %x differs from OPU Studio %x", p.writes, want)
			}
		})
	}
}

func TestPartialOldReplyDoesNotBlockNextRequest(t *testing.T) {
	p := &fakePort{}
	p.answer = func(req []byte) []byte {
		reply := respond(req, 0, req[8:len(req)-2])
		if len(p.writes) == 1 {
			// A valid echo followed by an incomplete, unrelated old frame.
			return append(reply, 0xa5, 0x5a, 1, 0x81, 0, 0, 128, 0)
		}
		return reply
	}
	c, err := New(p, 10*time.Millisecond)
	if err != nil {
		t.Fatal(err)
	}
	defer c.Close()
	for _, s := range []string{"one", "two"} {
		got, err := c.Ping(context.Background(), []byte(s))
		if err != nil || string(got) != s {
			t.Fatalf("PING %q blocked by an earlier partial frame: %q, %v", s, got, err)
		}
	}
	if len(p.writes) != 2 {
		t.Fatal("a request was repeated")
	}
}
